const med = xs => { const s=[...xs].sort((a,b)=>a-b); const n=s.length; return n? (n%2? s[(n-1)/2] : (s[n/2-1]+s[n/2])/2) : null; };
const P = {}; for (const [b,c] of [["stock","scalar"],["scalar","pie"],["stock","pie"]]) for (const ph of ["clean","audit","primary","shade"]) P[`${b}>${c}:${ph}`] = hardware.pairs(b,c,ph);
const summary = Object.fromEntries(Object.entries(P).map(([k,v])=>[k,{n:v.length, poses:[...new Set(v.map(r=>r.pose))].length, blocks:[...new Set(v.map(r=>r.block))].length}]));
summary

const poses = [...new Set(P["stock>pie:clean"].map(r=>r.pose))]; 
const sample = P["scalar>pie:clean"].filter(r=>r.pose===poses[0]);
({poses, sample})

const tbl = {};
for (const ph of ["clean","audit","primary","shade"]) {
  const sp = P[`stock>pie:${ph}`].filter(r=>r.pose==="default");
  const sc = P[`stock>scalar:${ph}`].filter(r=>r.pose==="default");
  const cp = P[`scalar>pie:${ph}`].filter(r=>r.pose==="default");
  tbl[ph] = {stockMs: med(sp.map(r=>r.baselineUs))/1000, scalarMs: med(cp.map(r=>r.baselineUs))/1000, pieMs: med(sp.map(r=>r.candidateUs))/1000,
   pctStockPie: med(sp.map(r=>r.savedPct)), pctScalarPie: med(cp.map(r=>r.savedPct)),
   usStockPie: med(sp.map(r=>r.savedUs)), usScalarPie: med(cp.map(r=>r.savedUs)), usStockScalar: med(sc.map(r=>r.savedUs)),
   cpSaved: cp.map(r=>r.savedUs), spSaved: sp.map(r=>r.savedUs), n: sp.length};
}
tbl

const byPose = (key) => Object.fromEntries(poses.map(p => [p, med(P[key].filter(r=>r.pose===p).map(r=>r.savedPct))]));
const sp = byPose("stock>pie:clean"), cp = byPose("scalar>pie:clean");
const rng = o => [Math.min(...Object.values(o)), Math.max(...Object.values(o))];
const signs = k => { const v=P[k]; return {pos: v.filter(r=>r.savedUs>0).length, neg: v.filter(r=>r.savedUs<0).length, zero: v.filter(r=>r.savedUs===0).length}; };
const crcAgree = Object.values(P).flat().every(r => r.outputCRC.length===3 && new Set(r.outputCRC).size===3);
const crcPerPose = poses.map(p => new Set(P["stock>pie:clean"].filter(r=>r.pose===p).map(r=>JSON.stringify(r.outputCRC))).size);
const strides = [...new Set(P["stock>pie:clean"].map(r=>r.stride))];
({spRange: rng(sp), cpRange: rng(cp), sp, cp, signs: Object.fromEntries(Object.keys(P).map(k=>[k,signs(k)])), crcAgree, crcPerPose, strides})

const crcByPose = Object.fromEntries(poses.map(p=>[p, P["stock>pie:clean"].find(r=>r.pose===p).outputCRC.join(",")]));
const crcPhase = ["clean","audit","primary","shade"].map(ph => P[`stock>pie:${ph}`].find(r=>r.pose==="default").outputCRC.join(","));
const strideByPose = Object.fromEntries(poses.map(p=>[p, P["stock>pie:clean"].find(r=>r.pose===p).stride]));
// position effect: pie absolute time by position within block, per pose normalized to pose median
const posEff = {};
for (const t of ["stock","scalar","pie"]) {
  const recs = t==="stock" ? P["stock>pie:clean"].map(r=>({pose:r.pose,us:r.baselineUs,pos:r.baselinePosition})) : t==="pie" ? P["stock>pie:clean"].map(r=>({pose:r.pose,us:r.candidateUs,pos:r.candidatePosition})) : P["scalar>pie:clean"].map(r=>({pose:r.pose,us:r.baselineUs,pos:r.baselinePosition}));
  const pm = Object.fromEntries(poses.map(p=>[p, med(recs.filter(r=>r.pose===p).map(r=>r.us))]));
  posEff[t] = [0,1,2].map(k => { const xs = recs.filter(r=>r.pos===k).map(r=>r.us-pm[r.pose]); return {pos:k, n:xs.length, medDevUs: med(xs)}; });
}
// block vs position mapping
const blockPos = [0,1,2,3,4,5].map(b => { const r1 = P["stock>pie:clean"].find(r=>r.block===b&&r.pose==="default"); const r2 = P["scalar>pie:clean"].find(r=>r.block===b&&r.pose==="default"); return {b, stock:r1.baselinePosition, pie:r1.candidatePosition, scalar:r2.baselinePosition}; });
({crcByPose, crcPhase, strideByPose, posEff, blockPos})

const L = hardware.loads(); 
const tr = [...new Set(L.map(r=>r.treatment))];
const lsum = Object.fromEntries(tr.map(t => { const v=L.filter(r=>r.treatment===t); return [t, {n:v.length, programs:[...new Set(v.map(r=>r.program))], medCompileMs: med(v.map(r=>r.compilerUs))/1000, medElapsedMs: med(v.map(r=>r.elapsedUs))/1000, medHeap: med(v.map(r=>r.peakJSBytes)), elf:[...new Set(v.map(r=>r.elfBytes))], seg:[...new Set(v.map(r=>r.segmentBytes))], crc:[...new Set(v.map(r=>r.elfCRC))], src:[...new Set(v.map(r=>r.sourceBytes))], blocks:[...new Set(v.map(r=>r.block))].length}]; }));
({tr, lsum, first: L.slice(0,3)})

const blk = [0,1,2,3,4,5].map(b => { const g = t => L.find(r=>r.block===b && r.treatment===t); return {b, pieMinusStock:(g("pie").compilerUs-g("stock").compilerUs)/1000, scalarMinusPie:(g("scalar").compilerUs-g("pie").compilerUs)/1000, pos:{stock:g("stock").position, scalar:g("scalar").position, pie:g("pie").position}, overheadUs: ["stock","scalar","pie"].map(t=>g(t).elapsedUs-g(t).compilerUs)}; });
const posC = [0,1,2].map(k => ({k, dev: L.filter(r=>r.position===k).map(r => r.compilerUs - med(L.filter(x=>x.treatment===r.treatment).map(x=>x.compilerUs)))}));
const arith = {breakEvenPrefilter: 70.324/1.616, breakEvenFirstTrial: (658.027-454.133)/1.616, breakEvenPieOnlyVsScalarPrefilter: 70.324/0.242, ratioTypedC: 56.069/9.535, saveStockPie: 57.692-56.069, savePieScalar: 56.3395-56.069, fetchSaveClean: 15532634-15038542, fetchScalarPie: 15110647-15038542, sizeDelta: 10308-9564, pieVsScalarSize: 10384-10308, rowDelta: 1688-944};
({blk, posC, arith})

const out = {};
for (const a of ["typed-stock","typed-scalar","typed-pie"]) { const arm = profiles.arm(a); out[a] = {totals: arm.totals ? arm.totals() : null, d: arm.describe()}; }
JSON.stringify(out).slice(0, 6000)

const vecEv = names.rows.filter(r => /Vectoriz|SLP|LoopUnroll|LSR|IndVar|LICM/i.test(r.header)); 
const row = run.function("row"); const middle = row.timeline("middle");
const vecTy = q.ir.instructions().resultType("<8 x i16>").count();
let vr; try { vr = q.run(vecTy.at(middle.at(middle.length ? middle.length-1 : 0).after)); } catch(e) { vr = String(e); }
({vecEv, tl: typeof middle.length, vr})

const res = {};
for (const v of ["checked","unchecked"]) { const r = a.variant(v); const f = r.function("row"); const tl = f.timeline("middle");
  for (const ord of [165,166,171,174,194]) { 
    let st; try { st = r.events("middle").at(ord); } catch(e) { res[v+ord] = String(e); continue; }
    const hdr = q.run(st.select("ordinal","header"));
    const anyVec = q.run(q.ir.instructions().where ? "w" : "nw");
    res[`${v}@${ord}`] = {hdr: hdr.rows ? hdr.rows[0] : hdr};
  }
}
res

const vr2 = {};
for (const v of ["checked","unchecked"]) { const f = a.variant(v).function("row"); const tl = f.timeline("middle");
  const m = q.ir.instructions().where(i => /</.test(String(i.resultType||i.type||""))).count();
  for (const ord of [165,166,171,174]) { try { const st = tl.at(ord); const r = q.run(q.ir.instructions().count().at(st.after)); const rv = q.run(m.at(st.after)); vr2[`${v}@${ord}`] = {pass: r.state && r.state.pass, all: r.value, vecLike: rv.value, status: rv.status}; } catch(e) { vr2[`${v}@${ord}`] = String(e).slice(0,160); } } }
vr2

const vr3 = {};
for (const v of ["checked","unchecked"]) { const f = a.variant(v).function("row"); const tl = f.timeline("middle");
  for (const ord of [165,166,171,174]) { try { const st = tl.at(ord); const all = q.run(q.ir.instructions().count().at(st.after)); const shuf = q.run(q.ir.instructions().opcode("shufflevector").count().at(st.after)); const v8 = q.run(q.ir.instructions().resultType("<8 x i16>").count().at(st.after)); const v4 = q.run(q.ir.instructions().resultType("<4 x i32>").count().at(st.after)); vr3[`${v}@${ord}`] = {pass: all.state.pass, cov: all.state.coverage, all: all.value, shuffles: shuf.value, v8i16: v8.value, v4i32: v4.value}; } catch(e) { vr3[`${v}@${ord}`] = String(e).slice(0,200); } } }
vr3

(function (root) {
    "use strict";
    function choose(region) {
        const n = Number.isInteger(region.constantTrips) ? region.constantTrips : 32;
        const groups = Math.floor(n / 8), tail = n % 8;
        const guards = 14 + 8 * region.writeStreams;
        const scalar = n * 18;
        const consume = 8 * 8;
        const grouped = guards + tail * 18 + groups * (consume + 7);
        const scores = {stock: scalar, scalar: groups ? grouped + groups * 24 : Infinity,
                        pie: groups ? grouped + groups * 3 + 3 : Infinity};
        let plan = "stock";
        for (const alternative of ["scalar", "pie"]) { if (scores[alternative] < scores[plan]) plan = alternative; }
        return {plan, scores, assumedTrips: n};
    }
    globalThis.simdChoose = choose;
})(globalThis);
const sel = [];
for (const w of [0,1,2,4]) for (const t of [8, 96, undefined, 3, 17, 7, 9, 16]) { const r = simdChoose({constantTrips: t, writeStreams: w}); sel.push({w, t: t===undefined?"dynamic":t, ...r}); }
// smallest n for which pie wins per writeStreams
const thr = [0,1,2,4,8].map(w => { let first=null; for (let n=1;n<=200;n++){ if (simdChoose({constantTrips:n, writeStreams:w}).plan==="pie"){first=n;break;} } const scalarEver = Array.from({length:200},(_,i)=>simdChoose({constantTrips:i+1,writeStreams:w}).plan).includes("scalar"); return {w, firstPie:first, scalarEverChosen: scalarEver}; });
({sel: sel.filter(s=>[8,96,"dynamic"].includes(s.t)), thr, n8w1: simdChoose({constantTrips:8,writeStreams:1}), n9: simdChoose({constantTrips:9,writeStreams:1}), n15: simdChoose({constantTrips:15,writeStreams:1})})

const sd = xs => { const m = xs.reduce((a,b)=>a+b,0)/xs.length; return Math.sqrt(xs.reduce((a,b)=>a+(b-m)**2,0)/(xs.length-1)); };
const noise = {};
for (const k of ["stock>pie:shade","scalar>pie:shade","stock>scalar:shade","scalar>pie:clean","scalar>pie:primary"]) { const v = P[k]; noise[k] = {sdUs: sd(v.map(r=>r.savedUs)), sdPct: sd(v.map(r=>r.savedPct)), minUs: Math.min(...v.map(r=>r.savedUs)), maxUs: Math.max(...v.map(r=>r.savedUs)), medUs: med(v.map(r=>r.savedUs))}; }
// within-pose residual sd for scalar>pie clean
const resid = P["scalar>pie:clean"].map(r => r.savedUs - med(P["scalar>pie:clean"].filter(x=>x.pose===r.pose).map(x=>x.savedUs)));
noise.cpCleanWithinPoseSdUs = sd(resid);
noise.compileSdMs = Object.fromEntries(["stock","scalar","pie"].map(t=>[t, sd(L.filter(r=>r.treatment===t).map(r=>r.compilerUs))/1000]));
noise
